package com.bank.pitr.service;
import com.bank.pitr.model.WalEntry;
import java.time.LocalDateTime;
import java.util.*;
import java.util.logging.*;

public class PitrEngine {
    private static final Logger log = Logger.getLogger(PitrEngine.class.getName());
    static {
        Handler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false); log.addHandler(h);
    }
    private final List<String> baseSnapshot;   // state at base-backup time
    private final List<WalEntry> wal;           // ordered changes after base
    public PitrEngine(List<String> baseSnapshot, List<WalEntry> wal) {
        this.baseSnapshot = baseSnapshot; this.wal = wal;
    }
    // Restore base, then replay WAL up to (and including) the target time only
    public List<String> recoverTo(LocalDateTime target) {
        List<String> state = new ArrayList<>(baseSnapshot);
        log.info(() -> "PITR restore base, replay WAL up to " + target);
        for (WalEntry e : wal) {
            if (e.getTs().isAfter(target)) {
                log.warning(() -> "STOP at " + e.getTs() + " (" + e.getOp() + ") — beyond target, skipped");
                break;                                   // stop exactly at target
            }
            apply(state, e);
            log.info(() -> "replayed " + e.getTs() + " " + e.getOp());
        }
        return state;
    }
    private void apply(List<String> state, WalEntry e) {
        if (e.getOp().startsWith("INSERT")) state.add(e.getOp().substring(7));
        else if (e.getOp().equals("DELETE all txn")) state.clear();
    }
}
