package com.bank.pitr;
import com.bank.pitr.model.WalEntry;
import com.bank.pitr.service.PitrEngine;
import java.time.LocalDateTime;
import java.util.*;
import java.util.logging.*;

public class PitrDemo {
    public static void main(String[] args) {
        LocalDateTime d = LocalDateTime.of(2026,10,25,0,0);
        List<String> base = new ArrayList<>(List.of("SAV2001 opening"));
        List<WalEntry> wal = List.of(
            new WalEntry(d.withHour(10), "INSERT txn-A SAV2001"),
            new WalEntry(d.withHour(13), "INSERT txn-B SAV2001"),
            new WalEntry(d.withHour(14).withMinute(5), "DELETE all txn"));   // the mistake
        PitrEngine pitr = new PitrEngine(base, wal);
        List<String> recovered = pitr.recoverTo(d.withHour(14).withMinute(4)); // 1 min before
        System.out.println("recovered state -> " + recovered);
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
